public static void forceDeleteOnExit(File file) throws IOException {
    // Check if the file is a directory
    if (file.isDirectory()) {
        // Delete the directory and all its sub-directories
        deleteDirectoryOnExit(file);
    } else {
        // Delete the file
        deleteOnExit(file);
