public static void deleteDirectoryOnExit(File dir) throws IOException {
    // Get the files and sub-directories list
    String[] files = dir.list();
    if (files == null) {
        // Throw an IOException if the directory is not accessible
        throw new IOException("Directory is not accessible: " + dir.getAbsolutePath());
    }
    // Delete all the files and sub-directories
    for (String file : files) {
        File current = new File(file);
        if (current.isDirectory()) {
            deleteDirectoryOnExit(current);
        } else {
            deleteOnExit(current);
        }
    }
    // Delete the current directory
    deleteOnExit(dir);
}

