    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Extract the path component from the URI
    String path = u.getPath();

    // Iterate over the characters in the path
    for (int i = 0; i < path.length(); i++) {
        // Check if the current character is a delimiter
        if (path.charAt(i) == '/') {
            // If so, add a new path segment to the list
            pathSegments.add(new PathSegmentImpl(path.substring(i + 1)));
        }
    }

    // If we need to decode the path segments, do so now
    if (decode) {
        for (PathSegmentImpl pathSegment : pathSegments) {
            pathSegment.setPath(URLDecoder.decode(pathSegment.getPath(), "UTF-8"));
        }
    }

