private boolean isTypeOnStack(final String descriptor) {
    if (outputFrameStack.isEmpty()) {
        return false;
    }

    // Handle method descriptors
    if (descriptor.startsWith("(")) {
        // Method descriptors have the form (...T...)V or (...T...):Ljava/lang/Object;
        String argumentTypes = descriptor.substring(1, descriptor.length() - 1);
        for (int i = 0; i < argumentTypes.length(); i += 2) {
            if (!isTypeOnStack(argumentTypes.substring(i, i + 2))) {
                return false;
            }
        }
        return true;
    }

    // Handle type descriptors
    String type = descriptor.substring(1); // Remove the leading type prefix
    if (!outputFrameStack.peek().getType().equals(type)) {
        return false;
    }
    return true;
}

