int function (DataOutput out, LinkedBuffer node) throws IOException {
  // Get the head node
  LinkedNode<Byte[]> head = node.getHead();

  // Write the head node to the output
  out.write(head.value);

  // Get the remaining byte array
  byte[] array = node.getFreeBuffer();

  // Write the remaining bytes to the output
  out.write(array);

  // Get the tail node
  LinkedNode<Byte[]> tail = node.getTail();

  // Write the tail node to the output
  out.write(tail.value);

  // Return the total content size of the buffer
  return node.getSize();
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // check if buffer is empty
    if (node.isEmpty()) {
        return 0;
    }

    // calculate the total content size of the buffer
    long totalContentSize = 0;
    LinkedNode<byte[]> currentNode = node.tail;
    while (currentNode != null) {
        totalContentSize += currentNode.data.length;
        currentNode = currentNode.previous;
    }

    // write content to output
    currentNode = node.tail;
    while (currentNode != null) {
        out.write(currentNode.data);
        currentNode = currentNode.previous;
    }

    return (int) totalContentSize;
}

