  if (charset.equals("US-ASCII") || charset.equals("ISO-8859-1") || charset.equals("UTF-8") || charset.equals("UTF-16BE") || charset.equals("UTF-16LE") || charset.equals("UTF-16"))
    return charset;

  // 4. Check if 'charset' starts with "ISO-8859-"
  if (charset.startsWith("ISO-8859-"))
    return "ISO-8859-" + charset.substring(9);

  // 5. Check if 'charset' starts with "WINDOWS-"
  if (charset.startsWith("WINDOWS-"))
    return "WINDOWS-" + charset.substring(8);

  // 6. Check if 'charset' starts with "UTF-"
  if (charset.startsWith("UTF-"))
    return "UTF_" + charset.substring(3);

  // 7. Check if 'charset' starts with "UTF16-"
  if (charset.startsWith("UTF16-"))
    return "UTF16_" + charset.substring(5);

  // 8. Return the original 'charset' as is
  return charset;
}

