@Override
public Action inspect(AtmosphereResource r) {
    if (!destroyed() && !isSuspendingOrSuspended(r) && !isStoppingOrStopped(r) && !isShuttingdown(r)) {
        switch (r.getTransport()) {
            case ATOM:
            case EMIT:
            case LONG_POLLING:
            case WEBSOCKET:
            case SHMEM:
                suspend(r);
                break;
            case UNRECOGNIZED:
                break;
        }
    }
    return Action.CONTINUE;
}

private boolean isSuspendingOrSuspended(AtmosphereResource r) {
    return suspending.get() || suspended.get();
}

private boolean isStoppingOrStopped(AtmosphereResource r) {
    return stopping.get() || stopped.get();
}

private boolean isShuttingdown(AtmosphereResource r) {
    return shuttingdown.get();
}

private void suspend(AtmosphereResource r) {
    if (!destroyed() && !suspending.get()) {
        suspending.set(true);
        try {
            if (!stopped.get()) {
                r.suspend();
            }
        } finally {
            suspending.set(false);
        }
    }
}

private void resume(AtmosphereResource r) {
    if (!destroyed() && suspended.get()) {
        suspended.set(false);
        if (!stopping.get()) {
            r.resume();
        }
    }
}

