public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Initialize a list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Iterate over the time ranges in the input list
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        // Get the start and end time of the current time range in milliseconds
        long startTime = timeRange.getStartTimeMillis();
        long endTime = timeRange.getEndTimeMillis();

        // Use the HprofReader to read the thread snapshots for the current time range
        try (HprofReader reader = new HprofReader(file)) {
            reader.setStartTime(startTime);
            reader.setEndTime(endTime);

            // Iterate over the thread snapshots in the current time range
            for (ThreadSnapshot threadSnapshot : reader.iterateThreadSnapshots()) {
                // Add each thread snapshot to the list
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

  ArrayList<ThreadSnapshot> snapshots = new ArrayList<>();
  RandomAccessFile raf = new RandomAccessFile(file, "r");
  int count = raf.readInt();
  for (int i = 0; i < count; i++) {
    long id = raf.readLong();
    long stackTraceId = raf.readLong();
    long startMillis = raf.readLong();
    long endMillis = raf.readLong();
    boolean detached = Boolean.parseBoolean(raf.readUTF());
    ThreadSnapshot snapshot = new ThreadSnapshot(id, stackTraceId, startMillis, endMillis, detached);
    snapshots.add(snapshot);
  }

  for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
    long startTime = timeRange.getStartTime();
    long endTime = timeRange.getEndTime();
    for (ThreadSnapshot snapshot : snapshots) {
      if (snapshot.getStartTime() >= startTime && snapshot.getEndTime() <= endTime) {
        snapshot.setAnalyzeTime(true);
      }
    }
  }

  return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // read the snapshot file
    SnapshotFile snapshotFile = new SnapshotFile(file);
    List<ThreadSnapshot> snapshots = snapshotFile.getThreadSnapshots();

    // filter snapshots based on time range
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : snapshots) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (snapshot.getStartTime() >= timeRange.getStartTime() && snapshot.getEndTime() <= timeRange.getEndTime()) {
                filteredSnapshots.add(snapshot);
            }
        }
    }

    return filteredSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshotList = new ArrayList<>();
    try (FileInputStream inputStream = new FileInputStream(file)) {
        HprofParser parser = new HprofParser(inputStream);
        HprofReader reader = parser.reader();
        reader.accept(new HprofVisitor() {
            @Override
            public void visit(ThreadSnapshot threadSnapshot) {
                long threadStartTime = threadSnapshot.getStartTime();
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.contains(threadStartTime)) {
                        snapshotList.add(threadSnapshot);
                        break;
                    }
                }
            }
        });
    }
    return snapshotList;
